local plr = game:GetService("Players").LocalPlayer local gui = plr:WaitForChild("PlayerGui") local workspace = game:GetService("Workspace") local uis = game:GetService("UserInputService") if gui:FindFirstChild("RobberCatsKeySystem") then gui:FindFirstChild("RobberCatsKeySystem"):Destroy() end if gui:FindFirstChild("RobberCatsHUD") then gui:FindFirstChild("RobberCatsHUD"):Destroy() end if workspace:FindFirstChild("AI_Loot_Markers") then workspace:FindFirstChild("AI_Loot_Markers"):Destroy() end
local function decodeHex(hex) local str = "" for i = 1, #hex, 2 do local code = tonumber(hex:sub(i, i+1), 16) if code then str = str .. string.char(code) end end return str end
local KeyUrl = decodeHex("68747470733a2f2f6c696e6b2d63656e7465722e6e65742f31303230373132342f43795476474a346662335861") pcall(function() if setclipboard then setclipboard(KeyUrl) elseif toclipboard then toclipboard(KeyUrl) end end)
local FoundLocksList, CurrentTPIndex, SavedBasePosition, LastRobberyPosition, IsScriptUnlocked = {}, 1, nil, nil, false
local function alert(titleText, msgText) game:GetService("StarterGui"):SetCore("SendNotification", {Title = titleText, Text = msgText, Duration = 1.5}) end
local function doScan() if workspace:FindFirstChild("AI_Loot_Markers") then workspace.AI_Loot_Markers:Destroy() end local markerFolder = Instance.new("Folder", workspace) markerFolder.Name = "AI_Loot_Markers" FoundLocksList, CurrentTPIndex = {}, 1 local count = 0 for _, prompt in ipairs(workspace:GetDescendants()) do if prompt:IsA("ProximityPrompt") and prompt.Parent:IsA("BasePart") then local objText, actText, parentName = prompt.ObjectText or "", prompt.ActionText or "", prompt.Parent.Name:lower() local comb = (objText .. " " .. actText .. " " .. parentName):lower() local isLock = actText:match("用钥匙拆毁") or actText:match("剪断电线") or comb:match("lock") or comb:match("замок") or comb:match("padlock") or comb:match("keypad") or comb:match("code") or parentName:match("gate") or parentName:match("safe") if isLock and not comb:match("box") and not comb:match("ящик") and not comb:match("chair") then table.insert(FoundLocksList, prompt.Parent) count = count + 1 local bg = Instance.new("BillboardGui", prompt.Parent) bg.Name = "AI_Loot_Text" bg.Size = UDim2.new(0, 300, 0, 40) bg.AlwaysOnTop = true bg.ExtentsOffset = Vector3.new(0, 4, 0) local tl = Instance.new("TextLabel", bg) tl.Size = UDim2.new(1, 0, 1, 0) tl.Text = "🎯 [LOCK APP #" .. count .. "]" tl.TextColor3 = Color3.fromRGB(255, 50, 50) tl.TextSize = 14 tl.Font = Enum.Font.SourceSansBold tl.BackgroundTransparency = 1 local h = Instance.new("Highlight", prompt.Parent) h.FillColor = Color3.fromRGB(180, 30, 30) h.OutlineColor = Color3.fromRGB(255, 255, 255) h.FillTransparency = 0.4 h.Parent = prompt.Parent end end end alert("🔍 SCANNER", "Target locks found: " .. count) end
local function doTpLock() local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not hrp then return end if #FoundLocksList > 0 then local currentPart = FoundLocksList[CurrentTPIndex] if currentPart and currentPart:IsA("BasePart") then hrp.CFrame = currentPart.CFrame + Vector3.new(0, 0, 2) alert("⚡ LOCK TP", "Teleported to lock #" .. CurrentTPIndex) CurrentTPIndex = CurrentTPIndex + 1 if CurrentTPIndex > #FoundLocksList then CurrentTPIndex = 1 end end else alert("⚠ SYSTEM NOTICE", "Target list is empty! Press Z to scan.") end end
local function doSaveBase() local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if hrp then SavedBasePosition = hrp.Position alert("📌 BASE SAVED", "Hideout position cached successfully!") end end
local function doTpBase() local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if hrp and SavedBasePosition then LastRobberyPosition = hrp.Position hrp.CFrame = CFrame.new(SavedBasePosition + Vector3.new(0, 2, 0)) alert("🏠 HIDEOUT BASE", "Loot secured! Return point set on [L]") else alert("❌ ERROR", "Base not set! Press C at your computer chair.") end end
local function doManualSave() local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if hrp then LastRobberyPosition = hrp.Position alert("💾 COORDS CACHED [R]", "Current robbery position saved!") else alert("❌ ERROR", "Failed to retrieve player vector position.") end end
local function doBackTp() local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if hrp and LastRobberyPosition then hrp.CFrame = CFrame.new(LastRobberyPosition + Vector3.new(0, 2, 0)) alert("🃟 BACK TP", "Returned to your saved crime scene spot!") else alert("❌ ERROR", "Memory slot empty! Press R at the loot location first.") end end
local function InitiateHackSuite() local sg = Instance.new("ScreenGui", gui) sg.Name = "RobberCatsHUD" sg.ResetOnSpawn = false local frame = Instance.new("Frame", sg) frame.Size = UDim2.new(0, 250, 0, 170) frame.Position = UDim2.new(0.02, 0, 0.3, 0) frame.BackgroundColor3 = Color3.fromRGB(15, 15, 18) frame.BackgroundTransparency = 0.4 Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 8) local titleHUD = Instance.new("TextLabel", frame) titleHUD.Size = UDim2.new(1, 0, 0, 25) titleHUD.Text = "🐈 ROBBER CATS KEYBOARD v5.9" titleHUD.TextColor3 = Color3.fromRGB(255, 255, 255) titleHUD.BackgroundColor3 = Color3.fromRGB(180, 30, 30) titleHUD.Font = Enum.Font.SourceSansBold titleHUD.TextSize = 12 Instance.new("UICorner", titleHUD).CornerRadius = UDim.new(0, 8) local function txt(str, posY, color) local l = Instance.new("TextLabel", frame) l.Size = UDim2.new(0.9, 0, 0, 20) l.Position = UDim2.new(0.05, 0, 0, posY) l.Text = str l.TextColor3 = color l.TextSize = 13 l.Font = Enum.Font.SourceSansBold l.TextXAlignment = Enum.TextXAlignment.Left l.BackgroundTransparency = 1 end txt("[Z] — SCAN ROOM CONTROLS", 35, Color3.fromRGB(255, 100, 100)) txt("[X] — CYCLE TELEPORT TO LOCKS", 55, Color3.fromRGB(200, 150, 255)) txt("[C] — SET CURRENT CHAIR AS BASE", 75, Color3.fromRGB(255, 200, 100)) txt("[K] — SECURE LOOT (TP TO BASE)", 95, Color3.fromRGB(120, 255, 120)) txt("[R] — SAVE POSITION MANUALLY", 115, Color3.fromRGB(255, 255, 100)) txt("[L] — RETURN TO CRIME SCENE (BACK TP)", 135, Color3.fromRGB(255, 120, 220)) IsScriptUnlocked = true alert("🐈 AI SYSTEM", "Access Granted! Enjoy the heist.", false) end
uis.InputBegan:Connect(function(input, gameProcessed) if gameProcessed or not IsScriptUnlocked then return end local key = input.KeyCode if key == Enum.KeyCode.Z then doScan() elseif key == Enum.KeyCode.X then doTpLock() elseif key == Enum.KeyCode.C then doSaveBase() elseif key == Enum.KeyCode.K then doTpBase() elseif key == Enum.KeyCode.R then doManualSave() elseif key == Enum.KeyCode.L then doBackTp() end end)
local KeySystem = Instance.new("ScreenGui", gui) KeySystem.Name = "RobberCatsKeySystem" KeySystem.ResetOnSpawn = false local MainFrame = Instance.new("Frame", KeySystem) MainFrame.Name = "MainFrame" MainFrame.BackgroundColor3 = Color3.fromRGB(20, 20, 25) MainFrame.Position = UDim2.new(0.4, 0, 0.4, 0) MainFrame.Size = UDim2.new(0, 280, 0, 110) Instance.new("UICorner", MainFrame).CornerRadius = UDim.new(0, 8) local Title = Instance.new("TextLabel", MainFrame) Title.Name = "Title" Title.BackgroundColor3 = Color3.fromRGB(180, 30, 30) Title.Size = UDim2.new(1, 0, 0, 30) Title.Font = Enum.Font.SourceSansBold Title.Text = "🐈 ROBBER CATS KEY SYSTEM" Title.TextColor3 = Color3.fromRGB(255, 255, 255) Title.TextSize = 14 Instance.new("UICorner", Title).CornerRadius = UDim.new(0, 8) local TextBox = Instance.new("TextBox", MainFrame) TextBox.BackgroundColor3 = Color3.fromRGB(30, 30, 35) TextBox.Position = UDim2.new(0.05, 0, 0.45, 0) TextBox.Size = UDim2.new(0.9, 0, 0, 35) TextBox.Font = Enum.Font.SourceSans TextBox.PlaceholderText = "Link Copied! Type key & press ENTER..." TextBox.Text = "" TextBox.TextColor3 = Color3.fromRGB(255, 255, 255) TextBox.TextSize = 13 Instance.new("UICorner", TextBox).CornerRadius = UDim.new(0, 6)
TextBox.FocusLost:Connect(function(enterPressed) if enterPressed then if TextBox.Text == "222" then KeySystem:Destroy() task.wait(0.2) InitiateHackSuite() else TextBox.Text = "" TextBox.PlaceholderText = "WRONG KEY! TRY AGAIN" end end end)
pcall(function() game:GetService("StarterGui"):SetCore("SendNotification", {Title = "📋 COPIED FULL LINK!", Text = "Open your browser and paste it to get key.", Duration = 3}) end)